package de.kopfzentrum.gam.laboratory;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/laboratory/orders") public class LaboratoryOrderController{private final LaboratoryOrderRepository repo;public LaboratoryOrderController(LaboratoryOrderRepository repo){this.repo=repo;}@GetMapping public List<LaboratoryOrder> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.list(q,status);}@PostMapping public LaboratoryOrder create(@RequestBody LaboratoryOrderRequest r,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.create(r,u.getUsername());}@PutMapping("/{id}") public LaboratoryOrder update(@PathVariable long id,@RequestBody LaboratoryOrderRequest r,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.update(id,r,u.getUsername());}@DeleteMapping("/{id}") public void delete(@PathVariable long id,@AuthenticationPrincipal AuthenticatedUser u){req(u);repo.delete(id);}private static void req(AuthenticatedUser u){if(u==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);}}
